const user = {
  name: "Anna",
  greet() {
    console.log(`Czesc, jestem ${this.name}`);
  },
};

user.greet(); // "Czesc, jestem Anna" - dziala poprawnie

const greetFn = user.greet; // wyciagniecie SAMEJ funkcji, bez "user"
greetFn(); // "Czesc, jestem undefined" - this juz NIE jest user!

function wykonaj(fn) {
  fn();
}

