const kot = {
  imie: "Filemon",
  miauknij() {
    console.log(`${this.imie} mowi: Miau!`);
  },
};

const samodzielnaFunkcja = kot.miauknij;
samodzielnaFunkcja();
// "undefined mowi: Miau!" - this zgubil powiazanie z kot, bo funkcja
// zostala wywolana samodzielnie, bez kropki poprzedzonej obiektem kot.

function wykonaj(fn) {
  console.log(fn());
}

const sklep = {
  nazwa: "Kwiaciarnia u Ani",
  podajNazwe() {
    return this.nazwa;
  },
};

wykonaj(sklep.podajNazwe);
// undefined - this gubi sie, bo funkcja wykonaj przyjmuje jedynie SAMA
// funkcje podajNazwe jako argument fn, bez zadnej informacji o tym, ze
// pierwotnie byla zwiazana z obiektem sklep. Wywolanie fn() wewnatrz
// wykonaj jest wywolaniem SAMODZIELNYM, bez kropki i obiektu przed nia.

const uzytkownik = { imie: "Kasia", pokazImie() { return this.imie; } };
const luznaFunkcja = uzytkownik.pokazImie;

console.log(uzytkownik.pokazImie()); // "Kasia" - wywolanie PRZEZ obiekt, this dziala
console.log(luznaFunkcja());          // undefined - wywolanie SAMODZIELNE, this zgubiony
// Ta sama funkcja daje rozne wyniki w zaleznosci wylacznie od SPOSOBU wywolania.

const panel = {
  widoczny: false,
  przelacz() {
    this.widoczny = !this.widoczny;
  },
};

setTimeout(panel.przelacz, 100);
// setTimeout wywoluje przekazana funkcje SAMODZIELNIE (bez kropki i bez
// obiektu panel przed nia) - this wewnatrz przelacz bedzie undefined,
// wiec this.widoczny = !this.widoczny rzuci blad probujac odczytac
// wlasciwosc widoczny z undefined.

const formularz = { dane: {}, zapisz(klucz, wartosc) { this.dane[klucz] = wartosc; } };
const zapiszWyciagniete = formularz.zapisz;

// zapiszWyciagniete("email", "test@test.pl");
// Blad: Cannot set properties of undefined (setting 'email')
// this jest undefined (funkcja wywolana samodzielnie), wiec proba
// this.dane['email'] = ... to proba odczytu wlasciwosci dane z undefined.

const uzytkownik = { imie: "Ola", pokazImie() { return this.imie; } };
const { pokazImie } = uzytkownik;

console.log(pokazImie()); // undefined
// Destrukturyzacja, mimo ze wyglada na proste "pobranie pola", technicznie
// wykonuje DOKLADNIE to samo, co przypisanie metody do osobnej zmiennej -
// kopiuje SAMA funkcje, bez informacji o obiekcie uzytkownik. Wywolanie
// pokazImie() jest wiec wywolaniem samodzielnym, this jest undefined.

const gra = { wynik: 0, dodajPunkt() { this.wynik++; } };
const funkcje = [gra.dodajPunkt, gra.dodajPunkt];

// funkcje.forEach(f => f()); -- rzuci blad (this undefined)
console.log(gra.wynik); // 0
// Kazdy element tablicy funkcje to wyciagnieta, samodzielna funkcja -
// zadna z nich nie "wie", ze pochodzi z obiektu gra, wiec this wewnatrz
// kazdej z nich jest undefined, a gra.wynik nigdy nie zostaje zwiekszony.

// Metoda TRACI powiazanie z this (staje sie "gola" funkcja) w trzech
// sytuacjach:
// 1. Przypisanie do zmiennej: const fn = obiekt.metoda;
// 2. Przekazanie jako argument: funkcja(obiekt.metoda), setTimeout(obiekt.metoda, ...)
// 3. Destrukturyzacja: const { metoda } = obiekt;
//
// Metoda ZACHOWUJE powiazanie z this TYLKO gdy jest wywolywana BEZPOSREDNIO
// przez oryginalny obiekt, z kropka tuz przed wywolaniem:
// obiekt.metoda() -- dziala zawsze poprawnie, this === obiekt
